insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_8_v1'
from (values
('128.22.c.1.A',3,'During a seventh-grade panel talk, a listener builds on another speaker''s point by:','["adding a related idea after restating the original", "repeating a different topic", "waiting silently", "correcting grammar aloud"]'::jsonb,0,'Building on others shows active listening.','original'),
('128.22.c.1.A',3,'A student isn''t sure what a speaker meant. The best clarifying question is:','["Can we be done?", "Could you explain what you meant by that term?", "Why are you talking?", "Who asked you?"]'::jsonb,1,'A clarifying question seeks meaning politely.','original'),
('128.22.c.1.B',3,'Restating oral instructions before starting a task helps a student:','["add extra steps", "skip the steps", "confirm each step was understood", "avoid questions"]'::jsonb,2,'Restating checks accuracy.','original'),
('128.22.c.1.B',3,'Increasingly complex oral instructions for a lab might include:','["only a title", "only sitting down", "one single word", "measuring, mixing, timing and recording results"]'::jsonb,3,'Complex instructions chain several tasks.','original'),
('128.22.c.1.C',3,'A critique of a film is strongest when the speaker:','["supports opinions with specific scenes", "only says it was good", "speaks without notes or details", "reads the credits"]'::jsonb,0,'Critiques need evidence.','original'),
('128.22.c.1.C',3,'During an oral critique, effective delivery includes:','["mumbling", "clear pacing, eye contact and appropriate gestures", "reading with no pauses", "turning away"]'::jsonb,1,'Delivery supports the message.','original'),
('128.22.c.1.D',3,'Accepting constructive feedback means a student:','["ignores the speaker", "argues every comment", "listens and considers using helpful suggestions", "leaves the group"]'::jsonb,2,'Open attitudes improve work.','original'),
('128.22.c.1.D',3,'Constructive feedback on a peer''s draft should be:','["personal insults", "only praise with no details", "vague and harsh", "specific, kind and focused on improving the work"]'::jsonb,3,'Useful feedback is specific and respectful.','original'),
('128.22.c.1.E',3,'Social communication skills in English include:','["greeting others and taking turns in conversation", "whispering at all times", "interrupting constantly", "avoiding eye contact"]'::jsonb,0,'Social language follows conventions.','original'),
('128.22.c.1.E',3,'Producing oral language in a contextualized way means the speaker:','["repeats the same sentence", "uses words that fit the situation and purpose", "speaks without any purpose", "uses only one word"]'::jsonb,1,'Language should match context.','original'),
('128.22.c.10.A',3,'A seventh grader reads an article warning about screen time. The author''s purpose is most likely to:','["give a recipe", "entertain with fantasy", "inform and persuade readers", "describe a dream"]'::jsonb,2,'Warning articles inform and persuade.','original'),
('128.22.c.10.A',3,'Which statement best describes an author''s message?','["the publisher''s name", "the number of chapters", "the date printed", "the central lesson or idea the writer wants conveyed"]'::jsonb,3,'The message is the main takeaway.','original'),
('128.22.c.10.B',3,'A writer arranges events by time order to show how an invention developed. The text structure is:','["chronological", "cause and effect", "problem and solution", "compare and contrast"]'::jsonb,0,'Time order is chronological.','original'),
('128.22.c.10.B',3,'Compare-and-contrast structure helps an author:','["define one word", "show similarities and differences between two subjects", "tell a story", "list steps in order"]'::jsonb,1,'This structure supports analysis of two things.','original'),
('128.22.c.10.C',3,'Bold headings and a captioned photo in an article help readers by:','["hiding the main idea", "making text unreadable", "organizing ideas and adding visual support", "removing details"]'::jsonb,2,'Print and graphic features guide readers.','original'),
('128.22.c.10.C',3,'A chart in a science article serves the purpose of:','["rhyming", "replacing the title", "entertaining only", "presenting data clearly at a glance"]'::jsonb,3,'Charts organize numeric information.','original'),
('128.22.c.10.D',3,'''The thunder shouted angrily at the town'' uses:','["personification", "rhyme", "alliteration", "simile"]'::jsonb,0,'Thunder is given a human action.','original'),
('128.22.c.10.D',3,'''The test was a mountain I had to climb'' is a:','["personification", "metaphor", "onomatopoeia", "pun"]'::jsonb,1,'A direct comparison without like or as.','original'),
('128.22.c.10.E',3,'A narrator who shares personal feelings uses which point of view?','["impersonal", "objective", "subjective", "neutral report"]'::jsonb,2,'Subjective narrators express feelings and opinions.','original'),
('128.22.c.10.E',3,'An objective point of view in a news story means the writer:','["exaggerates events", "persuades emotionally", "shares private feelings", "reports facts without personal opinions"]'::jsonb,3,'Objective writing stays neutral.','original'),
('128.22.c.10.F',3,'An author''s tone is the:','["attitude toward the subject", "font used", "length of the title", "number of paragraphs"]'::jsonb,0,'Tone reflects the writer''s attitude.','original'),
('128.22.c.10.F',3,'Sarcastic word choices in a column create a tone that is:','["neutral", "mocking", "shy", "admiring"]'::jsonb,1,'Sarcasm mocks or criticizes.','original'),
('128.22.c.10.G',3,'A speaker says, ''Are we really going to ignore this problem?'' This is a:','["factual statement", "heading", "rhetorical question", "citation"]'::jsonb,2,'A rhetorical question is asked for effect.','original'),
('128.22.c.10.G',3,'Direct address in a speech, such as ''You can make a difference,'' is used to:','["end the speech", "list sources", "hide the topic", "connect with the audience"]'::jsonb,3,'Speaking directly to listeners builds connection.','original'),
('128.22.c.11.A',3,'A student wants to persuade the school board to add recess time. The best genre is a:','["multi-paragraph argumentative text", "limerick", "menu", "recipe"]'::jsonb,0,'Persuasion fits argument.','original'),
('128.22.c.11.A',3,'Before drafting, a writer should identify:','["the final grade", "purpose, audience and topic", "the page count only", "the font"]'::jsonb,1,'These guide decisions.','original'),
('128.22.c.11.B.i',3,'Coherence in a paragraph means ideas:','["appear at random", "repeat constantly", "connect logically and flow smoothly", "contradict one another"]'::jsonb,2,'Coherence links ideas.','original'),
('128.22.c.11.B.ii',3,'Which addition best develops a paragraph about sea turtles?','["Some turtles are slow.", "Sea animals exist.", "Turtles are cool.", "Female sea turtles return to the same beach where they hatched to lay eggs."]'::jsonb,3,'Specific details add depth.','original'),
('128.22.c.11.B.ii',3,'An engaging idea shows depth of thought when it:','["explains why something matters with examples", "copies a definition", "names a topic only", "repeats the title"]'::jsonb,0,'Depth explains significance.','original'),
('128.22.c.11.C',3,'Revising for style includes:','["fixing only spelling", "replacing dull words with precise ones", "changing margins", "adding page numbers"]'::jsonb,1,'Style improves expression.','original'),
('128.22.c.11.C',3,'Combining short choppy sentences is a revision for:','["font", "page length", "sentence variety and flow", "spelling"]'::jsonb,2,'Combining sentences improves flow.','original'),
('128.22.c.11.D.i',3,'A compound sentence joins two:','["dependent phrases", "fragments only", "titles", "independent clauses"]'::jsonb,3,'Compound sentences have two or more independent clauses.','original'),
('128.22.c.11.D.i',3,'Which sentence is a fragment?','["Because the bus was late.", "We walked home.", "I called my mom.", "The bus was late."]'::jsonb,0,'It starts with a subordinator but is incomplete.','original'),
('128.22.c.11.D.ii',3,'Which sentence has a tense error?','["She walked to school and saw a friend.", "She walked to school and sees a friend.", "She walks to school and sees a friend.", "She will walk to school and see a friend."]'::jsonb,1,'The tenses shift without reason.','original'),
('128.22.c.11.D.ii',3,'Which shows the past perfect tense?','["They finishing before the bell.", "They will finish before the bell.", "They had finished before the bell rang.", "They finish before the bell rings."]'::jsonb,2,'Had plus a past participle.','original'),
('128.22.c.11.D.iii',3,'Which sentence correctly uses a conjunctive adverb?','["I studied hard consequently I passed.", "I studied; hard consequently, I passed.", "I studied hard, consequently I passed.", "I studied hard; consequently, I passed."]'::jsonb,3,'Semicolon before, comma after.','original'),
('128.22.c.11.D.iii',3,'A conjunctive adverb such as ''meanwhile'' mainly shows:','["a time relationship between ideas", "a question", "a comparison of color", "a contrast in size"]'::jsonb,0,'Meanwhile signals time.','original'),
('128.22.c.11.D.iv',4,'Which verb agrees with the subject? ''The members of the choir ___ rehearsing.''','["was", "are", "be", "is"]'::jsonb,1,'Members is plural.','original'),
('128.22.c.11.D.iv',4,'A prepositional phrase between a subject and verb:','["removes the verb", "always changes the verb", "does not change which noun the verb agrees with", "becomes the subject"]'::jsonb,2,'Agreement is with the true subject.','original'),
('128.22.c.11.D.v',3,'In ''The girls finished their project,'' the pronoun their refers back to:','["the verb", "the object", "the article", "the plural subject noun"]'::jsonb,3,'An antecedent is the noun a pronoun replaces.','original'),
('128.22.c.11.D.vi',3,'A subordinating conjunction connects:','["a dependent clause to an independent clause", "two titles", "two periods", "two nouns only"]'::jsonb,0,'It forms a complex sentence.','original'),
('128.22.c.11.D.vii',3,'Which of these must always be capitalized?','["ordinary nouns", "the names of months", "the names of seasons", "the word school in any use"]'::jsonb,1,'Months are proper nouns.','original'),
('128.22.c.11.D.vii',3,'A basic rule for capitalizing a title is to:','["capitalize every letter", "capitalize only the first word of every line", "capitalize the first and last words and major words in between", "capitalize only nouns at the end"]'::jsonb,2,'Major words in titles are capitalized.','original'),
('128.22.c.11.D.viii',3,'Commas set off an interrupter in which sentence?','["My neighbor a retired, nurse waved to us.", "My, neighbor a retired nurse waved to us.", "My neighbor a retired nurse waved to us.", "My neighbor, a retired nurse, waved to us."]'::jsonb,3,'The appositive is set off by commas.','original'),
('128.22.c.11.D.ix',3,'Which choice completes the sentence? ''The weather will ___ our plans.''','["affect", "afect", "effact", "effect"]'::jsonb,0,'Affect is the verb meaning to influence.','original'),
('128.22.c.11.D.ix',3,'Which sentence uses its correctly?','["The dog wagged its'' tail.", "The dog wagged its tail.", "The dog wagged it tail.", "The dog wagged it''s tail."]'::jsonb,1,'Its is possessive; it''s is a contraction.','original'),
('128.22.c.11.E',2,'Publishing for an appropriate audience means choosing a format that:','["has no title", "is hardest to read", "fits the people who will read it", "hides the writer"]'::jsonb,2,'Format should fit the audience.','original'),
('128.22.c.11.E',2,'A student could publish an opinion essay by:','["hiding it in a drawer", "skipping revision", "deleting the file", "submitting it to the school newspaper"]'::jsonb,3,'Publishing reaches readers.','original'),
('128.22.c.12.A',3,'Which element is most important in a personal narrative?','["a clear reflection on what the experience meant", "a glossary", "a bibliography", "a table of data"]'::jsonb,0,'Reflection gives narratives significance.','original'),
('128.22.c.12.A',3,'Imagery in a poem helps the reader:','["find the index", "picture sensory details", "skip lines", "count syllables only"]'::jsonb,1,'Imagery appeals to senses.','original'),
('128.22.c.12.B',3,'A strong conclusion in an informational essay:','["ends mid-thought", "adds a new topic", "restates the controlling idea in a fresh way", "repeats the introduction exactly"]'::jsonb,2,'Conclusions reinforce the controlling idea.','original'),
('128.22.c.12.B',3,'An informational essay organizes supporting ideas into:','["rhymed stanzas", "stage directions", "dialogue tags", "body paragraphs with facts and examples"]'::jsonb,3,'Body paragraphs develop the topic.','original'),
('128.22.c.12.C',3,'An argumentative text addresses a counterclaim to:','["show understanding of other views and strengthen the argument", "confuse readers", "avoid the topic", "shorten the text"]'::jsonb,0,'Addressing alternatives builds credibility.','original'),
('128.22.c.12.C',3,'Which is a reason (not a claim)?','["Our school should lengthen lunch.", "Longer lunch periods give students time to eat well.", "We want more lunch.", "Lunch should be longer."]'::jsonb,1,'A reason explains why a claim is true.','original'),
('128.22.c.12.D',3,'A business letter includes:','["only a title", "a rhyme scheme", "a heading, inside address, greeting, body and closing", "emoticons"]'::jsonb,2,'Formal letters follow a standard format.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_8_v1'
from (values
('128.22.c.12.D',3,'A letter registering a complaint about a product should:','["avoid specifics", "threaten the company", "use all capitals", "describe the problem and request a remedy politely"]'::jsonb,3,'Effective complaints are specific and courteous.','original'),
('128.22.c.13.A',3,'Which inquiry question is best for research?','["How have recycling programs changed waste levels in Texas cities?", "Do you like trash?", "What is garbage?", "Who recycles?"]'::jsonb,0,'It is open-ended and researchable.','original'),
('128.22.c.13.A',3,'Informal inquiry is different from formal inquiry because it:','["has strict deadlines", "is quick and exploratory without a full written plan", "requires a bibliography", "needs peer review"]'::jsonb,1,'Informal inquiry is casual exploration.','original'),
('128.22.c.13.B',3,'Which should a revised research plan include?','["only a title", "a drawing", "updated questions, sources and deadlines", "a menu"]'::jsonb,2,'Plans adapt as research proceeds.','original'),
('128.22.c.13.B',3,'A researcher revises a plan when:','["the title is chosen", "the deadline passes", "all questions are answered", "the first sources do not answer the question"]'::jsonb,3,'New information requires adjustments.','original'),
('128.22.c.13.C',3,'Secondary questions help a researcher by:','["breaking a big question into smaller parts", "ending research", "replacing sources", "skipping notes"]'::jsonb,0,'They guide refinement.','original'),
('128.22.c.13.C',3,'If the major question is answered by one fact, it should be:','["copied from the web", "refined to be deeper and more complex", "deleted", "kept as is"]'::jsonb,1,'A good question needs depth.','original'),
('128.22.c.13.D',3,'To gather relevant information from sources, a researcher can:','["guess", "skip indexes", "scan headings and use keywords", "read only titles"]'::jsonb,2,'These help locate information.','original'),
('128.22.c.13.D',3,'Which set of sources is the most varied?','["one photograph", "three blog posts", "two copies of one page", "an interview, a documentary and a government report"]'::jsonb,3,'Different formats provide different perspectives.','original'),
('128.22.c.13.E',3,'A letter written by a pioneer in 1850 is a:','["primary source", "citation", "glossary", "secondary source"]'::jsonb,0,'It was written during the time.','original'),
('128.22.c.13.E',3,'A magazine article analyzing the 1850 pioneer letters is a:','["primary source", "secondary source", "rhyme", "timeline"]'::jsonb,1,'It interprets the original.','original'),
('128.22.c.13.F',3,'Synthesizing means a researcher:','["ignores evidence", "copies one source", "blends information from sources to form new ideas", "lists titles"]'::jsonb,2,'Synthesis creates understanding.','original'),
('128.22.c.13.F',3,'Which sentence synthesizes two sources?','["Mentoring is a word.", "The interview was on Monday.", "The report is long.", "Both the report and the interview suggest that mentoring raises graduation rates."]'::jsonb,3,'It combines the sources'' shared finding.','original'),
('128.22.c.13.G',3,'Plagiarism includes:','["submitting someone else''s essay as your own", "citing a source", "quoting with credit", "summarizing with credit"]'::jsonb,0,'Using work without credit is plagiarism.','original'),
('128.22.c.13.H.i',3,'A website ending in .gov and written by agency scientists is likely:','["fictional", "credible", "biased", "anonymous"]'::jsonb,1,'Government agencies with experts are generally reliable.','original'),
('128.22.c.13.H.i',3,'A source with clear bias may:','["list all viewpoints fairly", "cite every perspective", "leave out facts that support other sides", "be neutral"]'::jsonb,2,'Bias favors one side.','original'),
('128.22.c.13.H.ii',3,'''This policy is the end of the world!'' is an example of:','["a fair summary", "a primary source", "a statistic", "hyperbole"]'::jsonb,3,'It is extreme exaggeration.','original'),
('128.22.c.13.H.ii',3,'An ad that shows a sad puppy to sell a donation plan uses:','["an emotional appeal", "a statistic", "a timeline", "a citation"]'::jsonb,0,'It targets feelings.','original'),
('128.22.c.13.I',3,'A works cited list shows:','["the table of contents", "the sources used in research", "the author''s diary", "the plot"]'::jsonb,1,'Citations credit sources.','original'),
('128.22.c.13.I',3,'Ethical use of source material includes:','["hiding sources", "inventing evidence", "citing ideas and quotations properly", "copying silently"]'::jsonb,2,'Ethics requires credit.','original'),
('128.22.c.13.J',3,'A research presentation delivered as a podcast uses which mode?','["written", "visual only", "silent", "oral"]'::jsonb,3,'Podcasts are audio.','original'),
('128.22.c.13.J',3,'A mode of delivery is multimodal when it:','["combines text, images and sound", "uses only handwriting", "has only a title", "is blank"]'::jsonb,0,'Multiple modes work together.','original'),
('128.22.c.2.A',3,'Applying phonetic knowledge helps a reader to:','["skip words", "decode unfamiliar words using sound-letter relationships", "guess pictures", "avoid reading"]'::jsonb,1,'Phonics supports decoding.','original'),
('128.22.c.2.A',3,'The word ''knight'' shows that English spelling:','["never uses vowels", "has no patterns", "has silent letters that do not match the sounds", "always matches sounds"]'::jsonb,2,'Silent k is a spelling feature.','original'),
('128.22.c.2.B',2,'Writing complete words and answers legibly helps because it:','["speeds up reading", "wastes pencils", "hides meaning", "lets others read the message"]'::jsonb,3,'Legibility supports communication.','original'),
('128.22.c.2.B',2,'A complete thought written clearly includes:','["a subject and a verb", "only an adjective", "only a noun", "only an article"]'::jsonb,0,'Complete thoughts need both.','original'),
('128.22.c.3.A',3,'A dictionary entry''s pronunciation guide helps a reader:','["count its letters", "say the word correctly", "find its page", "spell it backward"]'::jsonb,1,'It shows how to pronounce.','original'),
('128.22.c.3.A',3,'A glossary in a textbook is useful because it:','["lists the authors", "gives page numbers only", "defines key terms used in the book", "holds the quiz"]'::jsonb,2,'Glossaries define vocabulary.','original'),
('128.22.c.3.B',3,'In ''Unlike her calm sister, Mia was frantic,'' a contrast clue helps define frantic as:','["very calm", "very quiet", "very slow", "very anxious"]'::jsonb,3,'Unlike calm shows frantic is opposite.','original'),
('128.22.c.3.B',3,'In ''Because the road flooded, the bridge was impassable,'' a cause-and-effect clue suggests impassable means:','["impossible to cross", "new", "painted", "easy to cross"]'::jsonb,0,'Flooding caused the bridge to be closed.','original'),
('128.22.c.3.C',3,'The Greek root ''bio'' in biology means:','["time", "life", "earth", "water"]'::jsonb,1,'Bio means life.','original'),
('128.22.c.3.C',3,'The Latin root ''spect'' in inspect and spectator means:','["to run", "to build", "to look", "to speak"]'::jsonb,2,'Spect means look.','original'),
('128.22.c.3.E',3,'''Bank'' as in a river bank and a money bank is an example of a:','["antonym pair", "synonym pair", "prefix", "multiple-meaning word"]'::jsonb,3,'One spelling, several meanings.','original'),
('128.22.c.3.F',3,'An idiom such as ''spill the beans'' means:','["reveal a secret", "clean up", "drop food", "cook dinner"]'::jsonb,0,'Idioms have figurative meanings.','original'),
('128.22.c.3.F',3,'An analogy ''brave is to courageous as happy is to joyful'' shows:','["rhyme", "synonym relationships", "antonym relationships", "spelling"]'::jsonb,1,'Each pair has similar meanings.','original'),
('128.22.c.4',2,'Reading widely helps a student''s writing by:','["removing ideas", "limiting words", "exposing the student to new vocabulary and styles", "hiding models"]'::jsonb,2,'Reading builds language.','original'),
('128.22.c.4',2,'Listening to a read-aloud supports:','["no skills", "only handwriting", "only math", "vocabulary and comprehension growth"]'::jsonb,3,'Listening builds language skills.','original'),
('128.22.c.5',2,'A student listens to a podcast, reads a related article and writes a response. This activity:','["integrates listening, reading and writing", "uses only drawing", "uses no skills", "uses only math"]'::jsonb,0,'Several skills work together.','original'),
('128.22.c.5',2,'Discussing a text and then writing about it shows:','["only handwriting", "speaking and writing working together", "no connection", "only spelling"]'::jsonb,1,'Talk supports writing.','original'),
('128.22.c.6.A',3,'Setting a purpose for reading a recipe means:','["finding the longest word", "ignoring directions", "planning to follow the steps to cook the dish", "counting ingredients"]'::jsonb,2,'Purpose determines how to read.','original'),
('128.22.c.6.A',3,'A reader reading for entertainment is likely to choose:','["a manual", "a tax form", "a legal contract", "a novel they enjoy"]'::jsonb,3,'Purpose guides text choice.','original'),
('128.22.c.6.B',3,'Which question deepens understanding after reading?','["How might the story differ if the setting changed?", "What is the page count?", "How long is the index?", "Where is the cover?"]'::jsonb,0,'Analytical questions deepen thinking.','original'),
('128.22.c.6.B',3,'Asking questions during reading helps a reader to:','["skip passages", "monitor understanding and seek answers", "stop reading", "guess endings"]'::jsonb,1,'Questions keep readers engaged.','original'),
('128.22.c.6.C',3,'A reader predicts a story''s ending based on foreshadowing. The prediction relies on:','["cover color", "font type", "text clues", "page count"]'::jsonb,2,'Clues support predictions.','original'),
('128.22.c.6.C',3,'If new events show a prediction is wrong, the reader should:','["ignore the text", "hide the book", "stop reading", "correct it using the new evidence"]'::jsonb,3,'Predictions are revised.','original'),
('128.22.c.6.D',3,'A reader pictures a stormy night while reading. This is:','["visualizing", "scanning", "summarizing", "skimming"]'::jsonb,0,'Mental images deepen understanding.','original'),
('128.22.c.6.D',3,'Strong imagery for a mental picture includes:','["headings only", "details of color, sound and movement", "author names", "page numbers"]'::jsonb,1,'Sensory details create images.','original'),
('128.22.c.6.E',3,'Comparing a character''s struggle with a news story is a connection to:','["the font", "the cover", "society", "the index"]'::jsonb,2,'Text-to-world connections relate to society.','original'),
('128.22.c.6.E',3,'Linking two novels with similar themes is a connection to:','["glossaries", "fonts", "page numbers", "other texts"]'::jsonb,3,'Text-to-text connection.','original'),
('128.22.c.6.F',3,'''Eli''s hands trembled as he opened the envelope.'' A reader can infer Eli feels:','["nervous", "bored", "proud", "sleepy"]'::jsonb,0,'Trembling suggests nervousness.','original'),
('128.22.c.6.F',3,'An inference is stronger when it is backed by:','["the cover", "details from the text", "a hunch", "a random guess"]'::jsonb,1,'Evidence supports inferences.','original'),
('128.22.c.6.G',3,'A key idea is different from a supporting detail because it:','["is always shortest", "is a number", "carries the central meaning", "is always first"]'::jsonb,2,'Key ideas carry the meaning.','original'),
('128.22.c.6.G',3,'To evaluate details, a reader asks:','["Is this long?", "Is this in bold?", "Is this near the end?", "Does this detail support the main idea?"]'::jsonb,3,'Relevance to the main idea matters.','original'),
('128.22.c.6.H',3,'Synthesizing a news report and a documentary produces:','["a new understanding of the issue", "a copy of the report", "a list of dates", "a title"]'::jsonb,0,'Synthesis creates insight.','original'),
('128.22.c.6.H',3,'Which task requires synthesis?','["copying a poem", "explaining a theme using a poem and a short story", "counting lines", "listing authors"]'::jsonb,1,'It merges sources.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_8_v1'
from (values
('128.22.c.6.I',3,'When a passage is confusing, a reader can:','["guess blindly", "skip it", "reread, ask questions and use background knowledge", "stop reading"]'::jsonb,2,'Fix-up strategies restore meaning.','original'),
('128.22.c.7.A',2,'A personal connection response might say:','["Page ten is blank.", "The title is short.", "The font is large.", "This scene reminds me of moving to a new school."]'::jsonb,3,'Personal connections link to experience.','original'),
('128.22.c.7.A',2,'Self-selected texts are books a reader:','["picks to read for interest", "finds in a test", "never opens", "is forced to read"]'::jsonb,0,'Self-selected means chosen.','original'),
('128.22.c.7.B',3,'Which response compares two sources well?','["They have titles.", "Both articles discuss recycling, but one focuses on costs and the other on habits.", "Both are articles.", "One is long."]'::jsonb,1,'It identifies similarities and differences.','original'),
('128.22.c.7.B',3,'A response that demonstrates understanding should include:','["only a rating", "only a title", "specific details and explanation", "only a guess"]'::jsonb,2,'Details show comprehension.','original'),
('128.22.c.7.C',3,'Which is the best text evidence for ''The narrator is lonely''?','["The cafeteria was large.", "He ate lunch.", "Lunch was at noon.", "He ate lunch alone and wished someone would sit with him."]'::jsonb,3,'Actions and wishes show loneliness.','original'),
('128.22.c.7.C',3,'After giving text evidence, a writer should:','["explain how it supports the point", "repeat it", "move on silently", "delete it"]'::jsonb,0,'Evidence needs explanation.','original'),
('128.22.c.7.D',3,'A summary of a story should:','["include every detail", "include main events in order and be brief", "add the writer''s opinion only", "change the plot"]'::jsonb,1,'Summaries are concise and ordered.','original'),
('128.22.c.7.D',3,'Paraphrasing a quote means:','["copying it", "reversing it", "restating its meaning in your own words", "hiding it"]'::jsonb,2,'Paraphrase maintains meaning.','original'),
('128.22.c.7.E',3,'Annotating a text includes:','["copying the glossary", "erasing words", "skipping chapters", "underlining key ideas and writing notes in the margin"]'::jsonb,3,'Annotation records thinking.','original'),
('128.22.c.7.E',3,'A reading journal is a way to:','["record reactions and questions about a text", "grade the author", "skip reading", "hide the book"]'::jsonb,0,'Journals support reflection.','original'),
('128.22.c.7.F',3,'Using the word ''ambitious'' after learning it shows:','["copying quotes", "applying newly acquired vocabulary", "skipping reading", "avoiding words"]'::jsonb,1,'Using new words builds mastery.','original'),
('128.22.c.7.F',3,'Which sentence uses a newly learned word precisely?','["Candid mayor reporter.", "The reporters candid.", "The mayor''s candid answer surprised the reporters.", "The mayor''s answer candid it."]'::jsonb,2,'It uses candid correctly.','original'),
('128.22.c.7.G',3,'An explicit meaning is:','["hidden from the reader", "left out", "guessed", "stated directly in the text"]'::jsonb,3,'Explicit means plainly stated.','original'),
('128.22.c.7.G',3,'An implicit meaning requires the reader to:','["infer from clues", "copy a sentence", "count words", "skip a line"]'::jsonb,0,'Implicit meaning is suggested.','original'),
('128.22.c.7.H',3,'A formal email to a teacher should use:','["all capital letters", "polite vocabulary and a respectful tone", "slang and jokes", "text abbreviations"]'::jsonb,1,'Register fits the audience.','original'),
('128.22.c.7.H',3,'The voice in a response is the writer''s:','["font", "margin", "unique way of expressing ideas", "page count"]'::jsonb,2,'Voice reflects personality.','original'),
('128.22.c.7.I',3,'When a classmate presents better evidence, a thoughtful reader may:','["ignore the classmate", "repeat the old answer", "end the discussion", "reconsider and adjust a response"]'::jsonb,3,'Good thinkers adjust.','original'),
('128.22.c.7.I',3,'Reflection on a response asks:','["Does my answer still match the evidence?", "Is the desk clean?", "Is the paper white?", "Is the pen blue?"]'::jsonb,0,'Reflection ties answers to evidence.','original'),
('128.22.c.8.A',3,'A novel about perseverance and friendship contains:','["no themes", "multiple themes", "only one word", "only a setting"]'::jsonb,1,'Texts often have several themes.','original'),
('128.22.c.8.A',3,'To support a theme, a reader should cite:','["the page count", "the cover", "specific events or dialogue", "the font"]'::jsonb,2,'Evidence supports themes.','original'),
('128.22.c.8.B',3,'A character''s stubbornness leads her to ignore advice and cause a problem. This shows:','["a rhyme", "a title", "a setting", "how character qualities influence events"]'::jsonb,3,'Traits affect events.','original'),
('128.22.c.8.B',3,'A character''s kindness helps resolve a conflict. This is an example of:','["character qualities influencing the resolution", "setting only", "random luck only", "a font choice"]'::jsonb,0,'Qualities shape outcomes.','original'),
('128.22.c.8.C',3,'Foreshadowing is when an author:','["ends the story", "hints at events that will happen later", "changes the title", "describes the setting"]'::jsonb,1,'Foreshadowing creates anticipation.','original'),
('128.22.c.8.C',3,'Suspense in a story is created by:','["removing conflict", "revealing everything at once", "delaying the outcome to build tension", "ending early"]'::jsonb,2,'Suspense builds tension.','original'),
('128.22.c.8.D',3,'A story set in a blizzard limits what characters can do. This shows how:','["font influences plot", "cover influences plot", "title influences plot", "setting influences plot"]'::jsonb,3,'Setting creates obstacles.','original'),
('128.22.c.8.D',3,'A character raised in a small farming town may act differently in a big city because:','["setting shapes values and choices", "farms have chapters", "towns have fonts", "cities have glossaries"]'::jsonb,0,'Environment influences character.','original'),
('128.22.c.9.A',3,'A historical fiction story combines:','["only facts", "invented characters with real historical settings", "only fantasy", "only poems"]'::jsonb,1,'It blends fiction and history.','original'),
('128.22.c.9.A',3,'Science fiction commonly features:','["only letters", "only recipes", "imagined technology or future settings", "only real events"]'::jsonb,2,'The genre imagines science-based possibilities.','original'),
('128.22.c.9.B',3,'A rhyme scheme of ABAB means:','["no lines rhyme", "all lines rhyme", "only the last line rhymes", "alternating lines rhyme"]'::jsonb,3,'Lines one and three rhyme, as do two and four.','original'),
('128.22.c.9.B',3,'A dash or ellipsis in a poem can:','["create a pause or trailing effect", "end the poem", "change the rhyme", "delete a stanza"]'::jsonb,0,'Graphical elements shape rhythm.','original'),
('128.22.c.9.C',3,'A playwright reveals a character''s personality through:','["the glossary", "what the character says and does on stage", "the table of contents", "the bibliography"]'::jsonb,1,'Dialogue and staging build character.','original'),
('128.22.c.9.C',3,'A stage direction like ''(whispering)'' tells an actor:','["who wrote the play", "what the scene title is", "how to deliver a line", "when to leave the theater"]'::jsonb,2,'It guides performance.','original'),
('128.22.c.9.D.i',3,'Supporting evidence for a thesis should be:','["from rumors", "humorous only", "unrelated", "relevant and credible"]'::jsonb,3,'Good evidence fits the claim.','original'),
('128.22.c.9.D.i',3,'The controlling idea of an informational text is:','["the central point the author develops", "the page number", "the font", "the title page"]'::jsonb,0,'It controls the content.','original'),
('128.22.c.9.D.ii',3,'A bibliography at the end of a book:','["shows the author''s photo", "lists sources the author used", "gives the setting", "tells the plot"]'::jsonb,1,'Bibliographies list sources.','original'),
('128.22.c.9.D.ii',3,'Chapters and subsections help readers:','["avoid headings", "skip the index", "navigate and locate information", "hide ideas"]'::jsonb,2,'Organization aids navigation.','original'),
('128.22.c.9.D.iii',3,'A text with multiple topics and subtopics uses headings to:','["rhyme words", "shorten sentences", "hide the thesis", "organize categories and subcategories"]'::jsonb,3,'Headings show structure.','original'),
('128.22.c.9.D.iii',3,'Which organizational pattern groups ideas by type?','["classification", "chronological order", "stage directions", "rhyme scheme"]'::jsonb,0,'Classification sorts into categories.','original'),
('128.22.c.9.E.i',3,'The claim in an opinion piece is the:','["picture caption", "writer''s position on the issue", "publisher''s address", "date"]'::jsonb,1,'The claim is the stance.','original'),
('128.22.c.9.E.ii',3,'Considering alternatives in an argument means the author:','["avoids evidence", "hides the claim", "acknowledges other viewpoints and responds to them", "ignores everyone else"]'::jsonb,2,'This strengthens the argument.','original'),
('128.22.c.9.E.ii',3,'Types of evidence include:','["page numbers", "fonts and margins", "rhymes and riddles", "statistics, expert quotations and examples"]'::jsonb,3,'Arguments use varied evidence.','original'),
('128.22.c.9.E.iii',3,'A pamphlet written for new parents is aimed at:','["parents of babies", "pilots", "retirees", "chefs"]'::jsonb,0,'Content signals audience.','original'),
('128.22.c.9.E.iii',3,'The intended audience can be found by examining:','["the margins", "the language, topic and tone", "the font only", "the page number"]'::jsonb,1,'These reveal the reader.','original'),
('128.22.c.9.F',3,'A news website with video, text and interactive maps is:','["a poem", "a script", "multimodal", "only print"]'::jsonb,2,'It uses several modes.','original'),
('128.22.c.9.F',3,'A digital text may include hyperlinks that:','["delete the text", "lock the screen", "erase the page", "connect readers to related information"]'::jsonb,3,'Links expand content.','original'),
('128.22.c.11.B.i',3,'A writer adds ''as a result'' between two sentences to show:','["a cause-and-effect link", "a change of topic", "a list of examples", "a contrast in time"]'::jsonb,0,'Transitions signal relationships.','original'),
('128.22.c.11.B.i',3,'A strong introduction for an argumentative essay usually includes a:','["list of sources", "hook and a clear thesis statement", "glossary", "final conclusion"]'::jsonb,1,'Introductions frame the argument.','original'),
('128.22.c.11.D.v',3,'Which pronoun fixes this sentence? ''Every player must bring ___ own water bottle.''','["our", "its", "his or her", "their"]'::jsonb,2,'Singular antecedent needs a singular pronoun.','original'),
('128.22.c.11.D.vi',3,'In ''Both the principal and the counselor attended,'' the correlative conjunction pair is:','["not only ... but also", "either ... or", "neither ... nor", "both ... and"]'::jsonb,3,'Both pairs with and.','original'),
('128.22.c.11.D.viii',3,'Which sentence uses commas to set off a nonessential clause correctly?','["My brother, who plays tuba, joined the band.", "My brother who plays tuba, joined the band.", "My, brother who plays tuba joined the band.", "My brother who, plays tuba joined the band."]'::jsonb,0,'Nonessential clauses are set off by commas.','original'),
('128.22.c.11.D.viii',3,'A semicolon can replace:','["a comma in a list of one item", "a period between two closely related independent clauses", "a title", "an apostrophe"]'::jsonb,1,'Semicolons join related clauses.','original'),
('128.22.c.13.G',3,'A student restates an expert''s idea in new words and lists the expert in the works cited. This is:','["plagiarism", "a fallacy", "ethical paraphrasing", "fabrication"]'::jsonb,2,'Credit plus new wording is paraphrasing.','original'),
('128.22.c.13.G',3,'Which action avoids plagiarism?','["using a friend''s essay", "pasting it silently", "changing two words", "putting copied wording in quotation marks and citing it"]'::jsonb,3,'Exact words need quotes and credit.','original'),
('128.22.c.3.D',2,'Which word names a sequence?','["afterward", "tiny", "purple", "outside"]'::jsonb,0,'Afterward tells order in time.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_8_v1'
from (values
('128.22.c.3.E',3,'A reader sees ''bat'' in a baseball story and a cave story. This word is:','["an antonym", "a multiple-meaning word", "a homophone pair", "a prefix"]'::jsonb,1,'Context decides which meaning applies.','original'),
('128.22.c.3.E',3,'Which sentence uses a commonly confused term correctly?','["Theyre bringing there lunches over their.", "There bringing they''re lunches over their.", "They''re bringing their lunches over there.", "Their bringing there lunches over they''re."]'::jsonb,2,'They''re, their and there have different jobs.','original'),
('128.22.c.6.I',3,'A reader notices that three paragraphs made no sense. The best next step is to:','["skip to the end", "give up", "push on faster", "pause and reread with a question in mind"]'::jsonb,3,'Rereading repairs confusion.','original'),
('128.22.c.6.I',3,'Looking up an unfamiliar word while reading is an example of:','["a fix-up strategy", "a prediction", "a distraction", "a summary"]'::jsonb,0,'Fix-up strategies restore meaning.','original'),
('128.22.c.9.E.i',3,'The claim of an editorial usually appears:','["on the cover", "near the beginning", "only in the index", "in the footnotes"]'::jsonb,1,'Claims are typically stated early.','original'),
('128.22.c.9.E.i',3,'A claim differs from a fact because a claim:','["is always a quote", "is always a number", "can be argued and needs support", "is always proven"]'::jsonb,2,'Claims take a position.','original'),
('128.22.c.3.D',2,'Which word names a location?','["jump", "bright", "quietly", "downtown"]'::jsonb,3,'Downtown tells where.','original'),
('128.22.c.3.D',2,'Which word names a direction a student could follow?','["eastward", "slowly", "gently", "purple"]'::jsonb,0,'Eastward names a direction.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
